          { role: 'system', content: 'Te egy világszínvonalú tudományos fordító vagy. Fordítási szabályok: 1) A tudományos terminológiát pontosan őrizd meg. 2) A matematikai jelölések és LaTeX kód maradjon változatlan. 3) A fordítás legyen természetes, de szakmailag precíz magyar nyelven. 4) Ne adj hozzá semmit és ne hagyj ki semmit. 5) Őrizd meg a bekezdések szerkezetét.' },
          { role: 'user', content: chunk }
        ],
        stream: true,
        max_completion_tokens: model.max_output,
        temperature: model.temperature,
        top_p: model.top_p
      };
      let resp = await fetch(CEREBRAS_API_URL, {
        method: 'POST',
        headers: { Authorization: `Bearer ${CEREBRAS_API_KEY}`, 'Content-Type': 'application/json', Accept: 'text/event-stream' },
        body: JSON.stringify(payload)
      });
      if (resp.status===429) {
        await new Promise(r=>setTimeout(r,70000));
        resp = await fetch(CEREBRAS_API_URL, {
          method: 'POST',
          headers: { Authorization: `Bearer ${CEREBRAS_API_KEY}`, 'Content-Type': 'application/json', Accept: 'text/event-stream' },
          body: JSON.stringify(payload)
        });
      }
      if ([500,502,503].includes(resp.status)) {
        await new Promise(r=>setTimeout(r,5000));
        resp = await fetch(CEREBRAS_API_URL, {
          method: 'POST',
          headers: { Authorization: `Bearer ${CEREBRAS_API_KEY}`, 'Content-Type': 'application/json', Accept: 'text/event-stream' },
          body: JSON.stringify(payload)
        });
      }
      if (resp.status!==200) throw new Error('api '+model.name+' '+resp.status);
      const text = await resp.text();
      const lines = text.split('\n');
      const piece: string[] = [];
      for (const line of lines) {
        if (line.startsWith('data: ')) {
          const data = line.slice(6).trim();
          if (!data || data.includes('[DONE]')) continue;
          try {
            const obj = JSON.parse(data);
            const d = obj?.choices?.[0]?.delta?.content||'';
            if (d) piece.push(d);
          } catch {}
        }
      }
      parts.push(piece.join(''));
    }
  } finally {
    limiter.release();
  }
  const full = parts.join('\n\n');
  const timeMs = Date.now()-start;
  const tokens = estimate_tokens(full);
  return { text: full, timeMs, tokens };
}

async function scrape(url: string): Promise<string> {
  let resp = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36 JAIDE-Scraper/1.0', Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8' } });
  if (resp.status===429) {
    await new Promise(r=>setTimeout(r,15000));
    resp = await fetch(url);
  }
  if ([500,502,503].includes(resp.status)) {
    await new Promise(r=>setTimeout(r,5000));
    resp = await fetch(url);
  }
  if (!resp.ok) throw new Error('http '+resp.status);
  return await resp.text();
}

function extract_links(html: string, base: string): string[] {
  const links: string[] = [];
  const re = /href=["']([^"']+)["']/g;
  let m: RegExpExecArray | null;
  while ((m=re.exec(html))) {
    const link = m[1];
    if (link.startsWith('/abs/')||link.startsWith('/pdf/')||link.startsWith('/list/')||link.startsWith('/archive/')||link.startsWith('/search/')) {
      if (!link.includes('.pdf')) {
        const full = link.startsWith('http') ? link : (base + link);
        if (!links.includes(full)) links.push(full);
      }
    }
  }
  return links;
}

