          }
        };
        await write_jsonl(JSON.stringify(ex));
      } catch {}
    }
  }

  const crawlers = Array.from({length: CRAWL_CONCURRENCY}, ()=>crawlWorker());
  const translators = MODELS.flatMap(()=>Array.from({length: TRANSLATE_CONCURRENCY_PER_MODEL}, ()=>translateWorker()));
  await Promise.all(crawlers);
  crawlingDone = true;
  await Promise.all(translators);
}

